  "使用": "Use",
  "填写已有的多序列比对结果（例如 .fa 或 .fasta），不是未经比对的原始序列。": "Provide an existing multiple sequence alignment, such as .fa or .fasta, rather than unaligned raw sequences.",
  "样本名称应与表达矩阵中的样本一致；分组信息填写在这个表中。": "Sample names must match the expression matrix. Enter group assignments in this table.",
  "填写用于建网的表达矩阵文件，基因与样本排列按流程脚本要求准备。": "Provide the expression matrix for network construction, arranging genes and samples as required by the workflow.",
  "填写基因计数矩阵；不要用百分比或已取对数的表达量替代原始计数。": "Provide a gene count matrix. Do not replace raw counts with percentages or log-transformed expression.",
  "数值越小，保留的差异基因越少；是否调整应根据你的分析要求决定。": "Smaller values retain fewer differentially expressed genes. Adjust according to your analysis requirements.",
  "控制保留的表达变化幅度；阈值越大，变化幅度较小的基因越容易被过滤。": "Sets the minimum expression change retained. Larger thresholds exclude more genes with smaller changes.",
  "过滤平均表达量较低的基因。若改动，会改变进入共表达分析的基因集合。": "Filters genes with low mean expression. Changing this alters the gene set used for co-expression analysis.",
  "限制用于建网的基因数量；增加数量通常需要更多内存和更长计算时间。": "Limits the number of genes used to build the network. Larger values usually need more memory and time.",
  "限制模块的最少基因数；较大的值会减少很小的模块。": "Sets the minimum genes per module. Larger values reduce the number of very small modules.",
  "控制相近模块是否合并。调整会改变最终模块划分。": "Controls whether similar modules merge. Changing this affects the final module assignments.",
  "从这组候选值中选择建网软阈值，多个数值用逗号分隔。": "Select the network soft threshold from these candidate values. Separate values with commas.",
  "控制分群精细程度；通常增大后会得到更多细胞群。": "Controls clustering resolution. Larger values usually produce more cell groups.",
  "选择参与降维分析的高变基因数量；改变它会影响后续分群。": "Selects the number of highly variable genes for dimensionality reduction and affects downstream clustering.",
  "控制构建邻居图时参考的邻居数量，会影响局部结构和分群结果。": "Sets the number of neighbors used to construct the graph, affecting local structure and clustering.",
  "相同数据和设置下使用相同编号，有助于复现含随机步骤的结果。": "Using the same seed with the same data and settings helps reproduce results involving random steps.",
  "填写样本表中实际存在的对照组名称，必须与表中的拼写一致。": "Enter the control group name exactly as it appears in the sample table.",
  "填写样本表中实际存在的处理组名称，必须与表中的拼写一致。": "Enter the treatment group name exactly as it appears in the sample table.",
  "同时处理更多样本会增加总 CPU 和内存需求，须与任务资源配额协调。": "Processing more samples simultaneously increases total CPU and memory requirements. Coordinate this with the task's resources.",
  "每个样本占用的线程数；多个样本同时运行时要计算总线程需求。": "Threads used per sample. Account for the total when multiple samples run simultaneously.",
  "从第几列开始展示，第一列填写 1。": "First column to display, starting at 1.",
  "展示到第几列结束，包含该列；应不小于起始列。": "Last column to display, inclusive. It must not precede the first column.",
  "从基因上游提取的碱基数，会改变用于启动子分析的序列范围。": "Bases extracted upstream of each gene. This changes the sequence range used for promoter analysis.",
  "填写要搜索的 Pfam 结构域编号，多个编号按流程要求分隔。": "Enter the Pfam domain identifiers to search for, separated as required by the workflow.",
  "控制原始检验显著性筛选；最终结果还应结合校正显著性阈值。": "Sets the unadjusted significance filter. Interpret final results alongside the adjusted significance threshold.",
  "控制多重检验校正后的筛选范围；越小通常越严格。": "Sets the multiple-testing adjusted significance threshold. Smaller values are generally stricter.",
  "用于将替换数量换算为时间；需要与你研究的物种及时间单位相匹配。": "Converts substitution counts to time. It must match the species and time units being studied.",
  "样本或分组是否保留取决于这个细胞数阈值，请结合输入数据调整。": "This cell-count threshold determines which samples or groups are retained. Adjust it for your data.",
  "线粒体计数比例高于此阈值的细胞会被过滤。": "Cells exceeding this mitochondrial count percentage are filtered out.",
  "填写服务器已支持的运行配置名称；不要在这里输入 shell 命令。": "Enter a runtime profile supported by the server. Do not enter shell commands here.",
  "只供该数据服务访问使用；不要填写模型密钥或 SSH 密码。": "For access to this data service only. Do not enter a model key or server password.",
  "已有配置文件时填写路径；不确定内容时先准备样本表，再在对话中补齐配置。": "Enter the configuration file path if available. Otherwise prepare the sample table and complete the configuration in chat.",
  "寻找的基序长度下限，应不大于长度上限。": "Minimum motif length; it must not exceed the maximum length.",
  "寻找的基序长度上限，应不小于长度下限。": "Maximum motif length; it must not be below the minimum length.",
  "增加次数可提高随机检验的分辨率，但会增加计算时间。": "More permutations improve random-test resolution but require more computation time.",
  "增加次数会增加计算时间；保持一致便于比较重复运行结果。": "More iterations take longer. Keep this consistent when comparing repeated runs.",
  "仅在确实需要重新生成本任务结果时启用；不会赋予修改原始数据的权限。": "Enable only when this task's results must be regenerated. This does not permit modifying raw data.",
  "关闭在线获取时需要事先准备本地 KEGG 参考数据。": "Prepare local KEGG reference data before disabling online retrieval.",
  "软件专用附加选项。没有明确需要时留空或保留默认；这不是任意命令输入框。": "Additional options for this software. Leave blank or keep the default unless needed; this is not an arbitrary command field.",
  "扩展设置": "Additional settings",
  "需要填写": "Required",
  "按数据填写": "Set for your data",
