  "通常无需修改": "Usually unchanged",
  "请填写本次数据对应的文件或内容。": "Provide the file or content for this dataset.",
  "按本次数据填写；留空是否可自动查找取决于这一步的配置。": "Set for your dataset. Whether an empty value is discovered automatically depends on this step's configuration.",
  "有明确分析要求时再调整；保留默认值即可沿用当前流程设置。": "Adjust only for a specific analysis requirement. Otherwise keep the current workflow defaults.",
  "没有明确需要时保留默认值；修改仅影响本步骤的设置。": "Keep the default unless needed. Changes affect this step only.",
  "填写查询物种的蛋白序列文件。": "Provide the query species' protein sequence file.",
  "填写本次样本清单文件，具体列名按所用流程要求准备。": "Provide the sample manifest with the columns required by this workflow.",
  "供者的每个细胞群至少需要的细胞数；不足的组合不会进入汇总。": "Minimum cells required for each donor and cell group. Combinations below this threshold are excluded from aggregation.",
