  "由对话模型配置分析环境": "Let the model configure the analysis environment",
  "模型检查所选步骤的依赖、安装软件、读取错误日志并修正重试。登记的原始数据继续受到保护，操作记录保留可查。": "The model checks dependencies for the selected steps, installs software, reads error logs and retries repairs. Registered raw data remains protected and operations are logged.",
  "交给模型配置与分析": "Let the model configure and analyze",
  "数据路径与结果名称": "Data paths and result name",
  "告诉智能体要分析哪些数据，或在这里选择数据和步骤。结果统一保存到 OMaaX 工作文件夹，默认保留原始文件。": "Tell the agent what to analyze, or select data and steps here. Results are saved in the OMaaX working folder and original files are retained by default.",
  "也可以直接在对话中提供数据路径，由模型补齐输入配置。": "You can also provide data paths directly in chat and let the model complete the input configuration.",
  "数据所在目录": "Data directory",
  "直接填写右侧路径": "Enter the path on the right",
  "已用过的目录快捷选择。也可以在右侧直接填数据路径。": "Quickly select a previously used directory, or enter a data path on the right.",
  "本次数据路径": "Data path for this run",
  "例如 /home/你的账号/data，也可填 .": "For example, /home/user/data, or .",
  "可直接填写服务器绝对路径，无需登记。填 . 使用左侧目录；参考文件可在步骤参数中填写其他路径。": "Enter an absolute server path without registering it. Use . for the directory on the left. Other reference file paths can be set in step parameters.",
  "结果名称": "Result name",
  "给本次结果起一个便于辨认的名字，例如 rice_rnaseq。结果单独保存。": "Give these results a recognizable name, such as rice_rnaseq. They are saved separately.",
  "有未完成的参数编辑，可进入对话补齐；这些字段不会沿用旧值。": "Some parameter edits are incomplete. Complete them in chat; these fields will not reuse old values.",
  "计算资源 · 初始参考设置": "Compute resources · Initial settings",
  "模型可根据服务器与任务需求调整这些设置；实际运行遵守服务器可用资源。": "The model can adjust these settings for the server and task. Actual execution uses the resources available on the server.",
  "CPU 核数": "CPU cores",
  "当前步骤最多使用的 CPU 额度，不代表独占物理核心。": "Maximum CPU allocation for the current step. This does not reserve exclusive physical cores.",
  "内存上限（GiB）": "Memory limit (GiB)",
  "当前步骤及子程序合计的内存上限，超出可能停止。": "Total memory limit for the current step and its subprocesses. Exceeding it may stop execution.",
  "最长运行时间（小时）": "Maximum runtime (hours)",
  "全部步骤累计执行的时间上限；排队等待也有相同的时限，分别计时。": "Total execution time limit across all steps. Queue waiting has the same limit, timed separately.",
  "在对话中准备分析": "Prepare analysis in chat",
  "本次已选择": "Selected for this run:",
  "个步骤。输入配置及其他参数可交给模型填写，关键参数修改会应用到执行计划。": "steps. The model can fill input configuration and other parameters. Changes to key parameters apply to the execution plan.",
  "请先连接并选择服务器。": "Connect and select a server first.",
