  "在对话中补齐配置": "Complete configuration in chat",
  "把数据路径和样本分组告诉模型，补齐配置后自动提交分析，可在执行记录中查看进度。": "Give the model the data paths and sample groups. Analysis is submitted automatically once configuration is complete; view progress in execution records.",
  "执行记录": "Execution records",
