  "小时。原始文件只读，结果单独保存。": "hours. Original files are read-only and results are saved separately.",
  "已按本次设置配置，可在对话中调整": "Configured using these settings; adjust them in chat",
  "流程已提交，可查看执行进度。": "Workflow submitted. You can view execution progress.",
  "确认并运行": "Confirm and run",
  "调整参数": "Adjust parameters",
  "暂不运行": "Not now",
  "正在创建 ~/omaax 并检查基础环境": "Creating ~/omaax and checking the base environment",
  "环境配置状态暂时无法查询，重新连接后可以继续检查。": "Environment setup status is temporarily unavailable. Reconnect to check again.",
  "服务器磁盘空间不足。请检查保存位置的剩余空间，清理不再需要的文件后重试。": "The server is low on disk space. Check the destination's free space, remove unneeded files and retry.",
  "当前账号的存储配额不足，请联系管理员调整配额或改用其他保存位置。": "This account has insufficient storage quota. Ask an administrator to adjust it or use another location.",
  "服务器主机指纹与已保存记录不一致。请先向管理员核对，再重新确认连接。": "The server fingerprint does not match the saved record. Verify it with an administrator before confirming the connection again.",
  "SSH 认证未通过，请检查用户名、密码或私钥后重新连接。": "Server authentication failed. Check the username, password or private key and reconnect.",
  "基础运行镜像不可用或需要访问权限。请检查镜像地址及仓库权限，再重试环境准备；SSH 登录不受影响。": "The base runtime image is unavailable or requires access permission. Check its address and registry permissions, then retry setup. Server login is unaffected.",
  "连接镜像仓库时证书验证失败。请检查服务器时间、证书或网络代理配置后重试；SSH 登录不受影响。": "Certificate verification failed when connecting to the image registry. Check server time, certificates and network proxy configuration, then retry. Server login is unaffected.",
  "服务器无法连接镜像仓库，基础环境尚未准备完成。请检查服务器的外网连接或镜像仓库访问配置后重试；SSH 登录和文件浏览不受影响。": "The server cannot reach the image registry, so the base environment is not ready. Check its internet connection and registry access, then retry. Login and file browsing remain available.",
  "SSH 握手超时，尚未完成登录。请检查服务器地址、端口、网络及 SSH 服务是否正常。": "The server connection handshake timed out before login completed. Check the address, port, network and connection service.",
  "无法解析服务器地址。请检查主机名和服务器的网络、域名解析配置。": "The server address could not be resolved. Check the hostname, network and name resolution settings.",
  "服务器拒绝连接。请检查地址、端口是否正确，以及 SSH 服务和防火墙是否允许连接。": "The server refused the connection. Check the address, port, connection service and firewall.",
  "当前网络无法到达服务器。请检查网络连接及服务器地址后重试。": "The current network cannot reach the server. Check the network connection and server address, then retry.",
  "服务器系统未开放当前账号所需的隔离运行能力，请使用已配置环境的服务器或联系服务器管理员。": "This server does not provide the isolation required for the current account. Use a configured server or contact its administrator.",
  "环境准备未完成，请重新配置用户环境；无需提供管理员密码。": "Environment preparation is incomplete. Configure the user environment again; no administrator password is needed.",
  "服务器缺少基础运行组件，请先到“环境管理”准备基础环境。": "The server is missing base runtime components. Prepare its base environment in Environment management first.",
  "当前账号没有完成此操作的权限。请检查目录或文件的访问权限，必要时联系管理员。": "This account lacks permission for the operation. Check file and directory access, and contact an administrator if necessary.",
  "文件或目录不存在，或路径已发生变化。请检查路径后刷新重试。": "The file or directory does not exist, or its path has changed. Check the path, refresh and retry.",
  "文件内容校验未通过，传输尚未确认完成。请检查源文件是否变化，再重试传输。": "File content verification failed; the transfer is not confirmed complete. Check whether the source changed and retry.",
  "与服务器的连接已中断。请重新连接并刷新状态；已提交的任务请先核对进度，避免重复提交。": "The server connection was interrupted. Reconnect and refresh status. Check progress of submitted tasks before resubmitting to avoid duplicates.",
  "环境准备或检查超时。请稍后刷新进度或重试；SSH 登录不受影响。": "Environment preparation or checking timed out. Refresh progress later or retry. Server login is unaffected.",
  "数据传输超时。请检查两端连接并查看传输记录，再从中断处重试。": "Data transfer timed out. Check both connections and the transfer record, then resume from the interruption.",
  "服务器响应超时，请检查网络或稍后重试。已提交的任务请先刷新核对，避免重复提交。": "The server response timed out. Check the network or retry later. Refresh submitted tasks before resubmitting to avoid duplicates.",
  "服务器正在更新任务记录，请稍后刷新重试。": "The server is updating task records. Refresh again shortly.",
  "服务器返回的信息不完整或格式不正确，请刷新重试；若持续出现，请保留日志以便排查。": "The server returned incomplete or incorrectly formatted information. Refresh and retry. If the problem persists, retain the logs for troubleshooting.",
  "服务器环境准备未完成，请查看安装日志，确认所需组件和网络可用后重试。": "Server environment preparation is incomplete. Check the installation log, required components and network before retrying.",
  "服务器文件操作未完成，请检查路径和账号权限后重试。": "The server file operation did not complete. Check the path and account permissions, then retry.",
  "数据传输未完成，请查看传输记录并重试，原文件不会被删除。": "The data transfer did not complete. Check transfer records and retry. Original files will not be deleted.",
  "服务器连接未完成，请检查连接信息和网络后重试。": "The server connection did not complete. Check connection details and network, then retry.",
  "服务器操作未完成，请刷新状态后重试；若持续出现，请保留日志以便排查。": "The server operation did not complete. Refresh status and retry. Retain the logs if the issue persists.",
